"use strict";
window.LC_CHUNKS=window.LC_CHUNKS||{};window.LC_CHUNKS["university_electrical_engineering_core_de"]=window.LC_CHUNKS["university_electrical_engineering_core_de"]||{};window.LC_CHUNKS["university_electrical_engineering_core_de"][23]={"university_electrical_engineering_core_de:M23-L1":"<article class=\"lesson-standard\"><h1 id=\"L1\">M23-L1 – Transformator-Ersatzmodell und Prüfkonzepte<\/h1>\n<p><strong>Kursbereich:<\/strong> M23 – Bachelor: Elektrische Maschinen und Transformatoren<\/p>\n<p><strong>Niveau:<\/strong> Bachelor · Grundlagen<\/p>\n<p><strong>Vorwissen:<\/strong> <a\nhref=\"index.html?course=university_electrical-engineering-core&amp;module=M7&amp;lesson=L3&amp;syslang=de&amp;doclang=de&amp;theme=light\">M7-L3<\/a>.<\/p>\n<p><strong>Lernziel:<\/strong> Aus Messdatensätzen ein angenähertes\nErsatzschaltbild bestimmen und seine Grenzen erläutern.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Vom idealen zum realen Transformator<\/h2>\n<p>Die Grundlagen aus M7-L3 werden hier zur Parameteridentifikation\nerweitert. Für ein sinusförmiges Modell mit Übersetzungsverhältnis\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>a<\/mi><mo>=<\/mo><msub><mi>N<\/mi><mn>1<\/mn><\/msub><mi>/<\/mi><msub><mi>N<\/mi><mn>2<\/mn><\/msub><\/mrow><annotation encoding=\"application/x-tex\">a=N_1/N_2<\/annotation><\/semantics><\/math>\ngilt ideal\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>U<\/mi><mn>1<\/mn><\/msub><mi>/<\/mi><msub><mi>U<\/mi><mn>2<\/mn><\/msub><mo>=<\/mo><mi>a<\/mi><\/mrow><annotation encoding=\"application/x-tex\">U_1/U_2=a<\/annotation><\/semantics><\/math>\nund betragsmäßig\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>I<\/mi><mn>1<\/mn><\/msub><mi>/<\/mi><msub><mi>I<\/mi><mn>2<\/mn><\/msub><mo>=<\/mo><mn>1<\/mn><mi>/<\/mi><mi>a<\/mi><\/mrow><annotation encoding=\"application/x-tex\">I_1/I_2=1/a<\/annotation><\/semantics><\/math>.\nEine sekundäre Impedanz erscheint primär als\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>Z<\/mi><mn>2<\/mn><\/msub><mi>′<\/mi><mo>=<\/mo><msup><mi>a<\/mi><mn>2<\/mn><\/msup><msub><mi>Z<\/mi><mn>2<\/mn><\/msub><\/mrow><annotation encoding=\"application/x-tex\">Z_2\\prime=a^2 Z_2<\/annotation><\/semantics><\/math>.\nIm realen Gerät gehen Wicklungsverluste, Streufluss und endliche\nKernpermeabilität ein. Das angenäherte, auf eine Seite bezogene Modell\nenthält\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>R<\/mi><mi>k<\/mi><\/msub><mo>+<\/mo><mi>j<\/mi><msub><mi>X<\/mi><mi>k<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">R_k+jX_k<\/annotation><\/semantics><\/math>\nin Serie sowie\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>R<\/mi><mrow><mi>F<\/mi><mi>e<\/mi><\/mrow><\/msub><annotation encoding=\"application/x-tex\">R_{Fe}<\/annotation><\/semantics><\/math>\nparallel zu\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>j<\/mi><msub><mi>X<\/mi><mi>m<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">jX_m<\/annotation><\/semantics><\/math>\nam Eingang. Die Parallelzweige bilden Kernverluste und Magnetisierung\nab.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Parameter aus virtuellen Messdaten<\/h2>\n<p>Alle Spannungen und Ströme sind Effektivwerte; die folgenden\nBeziehungen gelten einphasig. Für den Leerlaufdatensatz gilt angenähert\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>I<\/mi><mi>w<\/mi><\/msub><mo>=<\/mo><msub><mi>P<\/mi><mn>0<\/mn><\/msub><mi>/<\/mi><msub><mi>U<\/mi><mn>0<\/mn><\/msub><\/mrow><annotation encoding=\"application/x-tex\">I_w=P_0/U_0<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>I<\/mi><mi>m<\/mi><\/msub><mo>=<\/mo><msqrt><mrow><msubsup><mi>I<\/mi><mn>0<\/mn><mn>2<\/mn><\/msubsup><mo>−<\/mo><msubsup><mi>I<\/mi><mi>w<\/mi><mn>2<\/mn><\/msubsup><\/mrow><\/msqrt><\/mrow><annotation encoding=\"application/x-tex\">I_m=\\sqrt{I_0^2-I_w^2}<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>R<\/mi><mrow><mi>F<\/mi><mi>e<\/mi><\/mrow><\/msub><mo>=<\/mo><msub><mi>U<\/mi><mn>0<\/mn><\/msub><mi>/<\/mi><msub><mi>I<\/mi><mi>w<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">R_{Fe}=U_0/I_w<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>X<\/mi><mi>m<\/mi><\/msub><mo>=<\/mo><msub><mi>U<\/mi><mn>0<\/mn><\/msub><mi>/<\/mi><msub><mi>I<\/mi><mi>m<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">X_m=U_0/I_m<\/annotation><\/semantics><\/math>.\nDie Verluste der stromdurchflossenen Wicklung werden dabei\nvernachlässigt. Aus einem Kurzschlussdatensatz ergeben sich\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>Z<\/mi><mi>k<\/mi><\/msub><mo>=<\/mo><msub><mi>U<\/mi><mi>k<\/mi><\/msub><mi>/<\/mi><msub><mi>I<\/mi><mi>k<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">Z_k=U_k/I_k<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>R<\/mi><mi>k<\/mi><\/msub><mo>=<\/mo><msub><mi>P<\/mi><mi>k<\/mi><\/msub><mi>/<\/mi><msubsup><mi>I<\/mi><mi>k<\/mi><mn>2<\/mn><\/msubsup><\/mrow><annotation encoding=\"application/x-tex\">R_k=P_k/I_k^2<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>X<\/mi><mi>k<\/mi><\/msub><mo>=<\/mo><msqrt><mrow><msubsup><mi>Z<\/mi><mi>k<\/mi><mn>2<\/mn><\/msubsup><mo>−<\/mo><msubsup><mi>R<\/mi><mi>k<\/mi><mn>2<\/mn><\/msubsup><\/mrow><\/msqrt><\/mrow><annotation encoding=\"application/x-tex\">X_k=\\sqrt{Z_k^2-R_k^2}<\/annotation><\/semantics><\/math>,\nwenn der Magnetisierungszweig vernachlässigbar ist. Messdaten\nverschiedener Bezugsseiten müssen erst umgerechnet werden.<\/p>\n<figure>\n<img src=\"../learning-courses-university-electrical-engineering-de/media/img/U_ELG_160_DE.svg\"\nalt=\"Transformator-Ersatzmodell und Prüfkonzepte\" />\n<figcaption aria-hidden=\"true\">Transformator-Ersatzmodell und\nPrüfkonzepte<\/figcaption>\n<\/figure>\n<p><em>Abbildung: Eigenes schematisches Lehrmodell; keine Auslegungs-\noder Prüfanleitung.<\/em><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel<\/h2>\n<p>Ein fiktiver Leerlaufdatensatz enthält 100 V, 0,5 A und 30 W. Daraus\nfolgen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>I<\/mi><mi>w<\/mi><\/msub><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>3<\/mn><\/mrow><annotation encoding=\"application/x-tex\">I_w=0,3<\/annotation><\/semantics><\/math>\nA,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>I<\/mi><mi>m<\/mi><\/msub><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>4<\/mn><\/mrow><annotation encoding=\"application/x-tex\">I_m=0,4<\/annotation><\/semantics><\/math>\nA,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>R<\/mi><mrow><mi>F<\/mi><mi>e<\/mi><\/mrow><\/msub><mo>=<\/mo><mn>333<\/mn><mo>,<\/mo><mn>3<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">Ω<\/mi><\/mrow><annotation encoding=\"application/x-tex\">R_{Fe}=333,3\\,\\Omega<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>X<\/mi><mi>m<\/mi><\/msub><mo>=<\/mo><mn>250<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">Ω<\/mi><\/mrow><annotation encoding=\"application/x-tex\">X_m=250\\,\\Omega<\/annotation><\/semantics><\/math>.\nEin zweiter, auf dieselbe Seite bezogener Datensatz enthält 10 V, 5 A\nund 30 W. Hieraus ergeben sich\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>Z<\/mi><mi>k<\/mi><\/msub><mo>=<\/mo><mn>2<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">Ω<\/mi><\/mrow><annotation encoding=\"application/x-tex\">Z_k=2\\,\\Omega<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>R<\/mi><mi>k<\/mi><\/msub><mo>=<\/mo><mn>1<\/mn><mo>,<\/mo><mn>2<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">Ω<\/mi><\/mrow><annotation encoding=\"application/x-tex\">R_k=1,2\\,\\Omega<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>X<\/mi><mi>k<\/mi><\/msub><mo>=<\/mo><mn>1<\/mn><mo>,<\/mo><mn>6<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">Ω<\/mi><\/mrow><annotation encoding=\"application/x-tex\">X_k=1,6\\,\\Omega<\/annotation><\/semantics><\/math>.\nDie beiden Datensätze bestimmen unterschiedliche Zweige des Modells.<\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Validierung und Grenzen<\/h2>\n<p>Mit dem Ersatzmodell lassen sich Spannungsänderung und Verluste unter\nvariierender Last abschätzen. Sättigung, Einschaltstrom,\nFrequenzabhängigkeit und temperaturabhängige Wicklungswiderstände\nerfordern weitere Modelle. Unplausible Daten, etwa Wirkleistung oberhalb\nder Scheinleistung, müssen vor der Parameterschätzung geklärt werden.\nDas Selbststudium arbeitet ausschließlich mit simulierten Datensätzen;\nreale Transformatorprüfungen gehören in ein beaufsichtigtes\nFachlabor.<\/p>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Wie groß ist die primär bezogene Last bei a=2 und einer sekundären\nLast von 5 Ω?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Welche Zweige beschreibt der Leerlaufdatensatz?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Warum ist P größer als U I im sinusförmigen Einphasenmodell\nunplausibel?<\/div><\/li>\n<\/ol>\n<details class=\"lc-solutions\" data-lc-section=\"S5\"><summary>Lösungen anzeigen<\/summary>\n<div>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">20 Ω.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Kernverlust- und Magnetisierungszweig.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Der Betrag der Wirkleistung kann die Scheinleistung nicht\nüberschreiten.<\/div><\/li>\n<\/ol>\n<\/div>\n<\/details>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen<\/h2>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://ecelabs.njit.edu/ece342/lab3.php\">NJIT ECE 342 –\nPower Transformer Open and Short Circuit Tests<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · HTML lines 42–52,\n69–81, 98–100; equivalent circuit and parameter identification · Zuletzt\nabgerufen: 2026-11-25 · Inhaltlich geprüft: 2026-11-25<\/div><\/li>\n<\/ul>\n<\/article>","university_electrical_engineering_core_de:M23-L2":"<article class=\"lesson-standard\"><h1 id=\"L2\">M23-L2 – Gleichstrommaschinen<\/h1>\n<p><strong>Kursbereich:<\/strong> M23 – Bachelor: Elektrische Maschinen und Transformatoren<\/p>\n<p><strong>Niveau:<\/strong> Bachelor · Grundlagen<\/p>\n<p><strong>Vorwissen:<\/strong> <a\nhref=\"index.html?course=university_electrical-engineering-core&amp;module=M23&amp;lesson=L1&amp;syslang=de&amp;doclang=de&amp;theme=light\">M23-L1<\/a>.<\/p>\n<p><strong>Lernziel:<\/strong> Drehmoment, Gegen-EMK und Leistungsfluss\neiner fremderregten Gleichstrommaschine berechnen.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufbau und Kommutierung<\/h2>\n<p>Bei einer klassischen Gleichstrommaschine erzeugt der Stator das\nErregerfeld; der Rotor trägt die Ankerwicklung. Bürsten und Kommutator\nvermitteln den Stromübergang und die passende Stromrichtung in den\nRotorleitern. Die mechanische Kommutierung verursacht Verschleiß.\nBürstenlose Motoren mit elektronischer Kommutierung sind dagegen\ntypischerweise Synchronmaschinen. Fremd-, Neben- und Reihenschluss\nunterscheiden sich durch die Erregerschaltung.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Stationäres Modell<\/h2>\n<p>Für konstante Erregung, vernachlässigten Bürstenspannungsfall und\nMotorzählrichtung gilt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E<\/mi><mo>=<\/mo><mi>k<\/mi><mi>ω<\/mi><\/mrow><annotation encoding=\"application/x-tex\">E=k\\omega<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>U<\/mi><mo>=<\/mo><mi>E<\/mi><mo>+<\/mo><msub><mi>R<\/mi><mi>a<\/mi><\/msub><msub><mi>I<\/mi><mi>a<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">U=E+R_a I_a<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>T<\/mi><mi>e<\/mi><\/msub><mo>=<\/mo><mi>k<\/mi><msub><mi>I<\/mi><mi>a<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">T_e=k I_a<\/annotation><\/semantics><\/math>.\nIn SI besitzt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>k<\/mi><annotation encoding=\"application/x-tex\">k<\/annotation><\/semantics><\/math>\ndenselben Zahlenwert in V s/rad und N m/A. Damit ist die umgesetzte\nLeistung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>P<\/mi><mrow><mi>e<\/mi><mi>m<\/mi><\/mrow><\/msub><mo>=<\/mo><mi>E<\/mi><msub><mi>I<\/mi><mi>a<\/mi><\/msub><mo>=<\/mo><msub><mi>T<\/mi><mi>e<\/mi><\/msub><mi>ω<\/mi><\/mrow><annotation encoding=\"application/x-tex\">P_{em}=EI_a=T_e\\omega<\/annotation><\/semantics><\/math>.\nDie Ankerkupferverluste betragen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msubsup><mi>I<\/mi><mi>a<\/mi><mn>2<\/mn><\/msubsup><msub><mi>R<\/mi><mi>a<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">I_a^2 R_a<\/annotation><\/semantics><\/math>.\nDas elektromagnetische Drehmoment ist nicht das verfügbare\nWellendrehmoment, wenn Reibung oder andere Verluste auftreten.<\/p>\n<figure>\n<img src=\"../learning-courses-university-electrical-engineering-de/media/img/U_ELG_161_DE.svg\" alt=\"Gleichstrommaschinen\" />\n<figcaption aria-hidden=\"true\">Gleichstrommaschinen<\/figcaption>\n<\/figure>\n<p><em>Abbildung: Eigenes schematisches Lehrmodell; keine Auslegungs-\noder Prüfanleitung.<\/em><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel<\/h2>\n<p>Bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>U<\/mi><mo>=<\/mo><mn>48<\/mn><\/mrow><annotation encoding=\"application/x-tex\">U=48<\/annotation><\/semantics><\/math>\nV,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>R<\/mi><mi>a<\/mi><\/msub><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>4<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">Ω<\/mi><\/mrow><annotation encoding=\"application/x-tex\">R_a=0,4\\,\\Omega<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>k<\/mi><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">k=0,2<\/annotation><\/semantics><\/math>\nV s/rad und\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ω<\/mi><mo>=<\/mo><mn>200<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\omega=200<\/annotation><\/semantics><\/math>\nrad/s erhält man\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E<\/mi><mo>=<\/mo><mn>40<\/mn><\/mrow><annotation encoding=\"application/x-tex\">E=40<\/annotation><\/semantics><\/math>\nV,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>I<\/mi><mi>a<\/mi><\/msub><mo>=<\/mo><mn>20<\/mn><\/mrow><annotation encoding=\"application/x-tex\">I_a=20<\/annotation><\/semantics><\/math>\nA und\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>T<\/mi><mi>e<\/mi><\/msub><mo>=<\/mo><mn>4<\/mn><\/mrow><annotation encoding=\"application/x-tex\">T_e=4<\/annotation><\/semantics><\/math>\nN m. Die Ankeraufnahme beträgt 960 W, der Ankerverlust 160 W und die\nelektromagnetisch umgesetzte Leistung 800 W. Die Erregungsaufnahme und\nmechanische Verluste sind in dieser Teilbilanz nicht enthalten.<\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Kennlinie und Betriebsgrenzen<\/h2>\n<p>Die ideale Drehmoment-Drehzahl-Gerade lautet\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>T<\/mi><mi>e<\/mi><\/msub><mo>=<\/mo><mi>k<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>U<\/mi><mo>−<\/mo><mi>k<\/mi><mi>ω<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><msub><mi>R<\/mi><mi>a<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">T_e=k(U-k\\omega)/R_a<\/annotation><\/semantics><\/math>.\nBei positivem\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>ω<\/mi><annotation encoding=\"application/x-tex\">\\omega<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E<\/mi><mo>&gt;<\/mo><mi>U<\/mi><\/mrow><annotation encoding=\"application/x-tex\">E&gt;U<\/annotation><\/semantics><\/math>\nwird der Ankerstrom negativ; der elektrische Leistungsfluss kann sich\numkehren. Das setzt eine geeignete Quelle bzw. Umrichtertopologie\nvoraus. Ein Reihenschlussmotor besitzt keine konstante Erregung, weshalb\ndiese Gerade nicht übertragbar ist. Stromgrenze, Kommutierung, Erwärmung\nund mechanische Drehzahlgrenze beschränken alle realen\nBetriebspunkte.<\/p>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Wie groß ist E bei 150 rad/s im Beispiel?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Wie groß ist dann der Ankerstrom?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Welche Verlustleistung bleibt bei I=0 im idealen\nAnkerwiderstand?<\/div><\/li>\n<\/ol>\n<details class=\"lc-solutions\" data-lc-section=\"S5\"><summary>Lösungen anzeigen<\/summary>\n<div>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">30 V.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">45 A; lediglich ein Modellwert ohne Strombegrenzung.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">0 W.<\/div><\/li>\n<\/ol>\n<\/div>\n<\/details>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen<\/h2>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a\nhref=\"https://ocw.mit.edu/courses/6-685-electric-machines-fall-2013/2aec052d0c82b73a7b6c72d78f3a796d_MIT6_685F13_chapter6.pdf\">J.\nL. Kirtley, MIT 6.685 – DC (Commutator) and Permanent Magnet\nMachines<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · PDF text lines 130–174, 217–228; first page screenshot\navailable; DC model and excitation · Zuletzt abgerufen: 2026-11-25 ·\nInhaltlich geprüft: 2026-11-25<\/div><\/li>\n<\/ul>\n<\/article>","university_electrical_engineering_core_de:M23-L3":"<article class=\"lesson-standard\"><h1 id=\"L3\">M23-L3 – Synchronmaschinen<\/h1>\n<p><strong>Kursbereich:<\/strong> M23 – Bachelor: Elektrische Maschinen und Transformatoren<\/p>\n<p><strong>Niveau:<\/strong> Bachelor · Grundlagen<\/p>\n<p><strong>Vorwissen:<\/strong> <a\nhref=\"index.html?course=university_electrical-engineering-core&amp;module=M23&amp;lesson=L2&amp;syslang=de&amp;doclang=de&amp;theme=light\">M23-L2<\/a>.<\/p>\n<p><strong>Lernziel:<\/strong> Synchrondrehzahl und Leistungswinkelmodell\neiner symmetrischen Vollpolmaschine anwenden.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Drehfeld und Erregung<\/h2>\n<p>Drei räumlich versetzte, symmetrisch gespeiste Statorwicklungen\nerzeugen ein umlaufendes Feld. Der Rotor einer Synchronmaschine folgt\ndiesem Feld im stationären Betrieb. Bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>p<\/mi><annotation encoding=\"application/x-tex\">p<\/annotation><\/semantics><\/math>\nPolpaaren und Frequenz\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>f<\/mi><annotation encoding=\"application/x-tex\">f<\/annotation><\/semantics><\/math>\ngilt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>n<\/mi><mi>s<\/mi><\/msub><mo>=<\/mo><mn>60<\/mn><mi>f<\/mi><mi>/<\/mi><mi>p<\/mi><\/mrow><annotation encoding=\"application/x-tex\">n_s=60f/p<\/annotation><\/semantics><\/math>\nin min⁻¹ und\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>ω<\/mi><mi>s<\/mi><\/msub><mo>=<\/mo><mn>2<\/mn><mi>π<\/mi><mi>f<\/mi><mi>/<\/mi><mi>p<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\omega_s=2\\pi f/p<\/annotation><\/semantics><\/math>\nin rad/s. Das Rotorfeld kann elektrisch erregt oder permanentmagnetisch\nerzeugt sein. Reluktanzmaschinen nutzen richtungsabhängige magnetische\nEigenschaften.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Vereinfachtes Leistungswinkelmodell<\/h2>\n<p>Für den symmetrischen Vollpolgenerator mit vernachlässigtem\nStatorwiderstand gilt pro Phase\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E<\/mi><mo>=<\/mo><mi>V<\/mi><mo>+<\/mo><mi>j<\/mi><msub><mi>X<\/mi><mi>s<\/mi><\/msub><mi>I<\/mi><\/mrow><annotation encoding=\"application/x-tex\">E=V+jX_s I<\/annotation><\/semantics><\/math>.\nDabei sind\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>E<\/mi><mo>,<\/mo><mi>V<\/mi><\/mrow><annotation encoding=\"application/x-tex\">E,V<\/annotation><\/semantics><\/math>\nEffektivwert-Zeiger,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>I<\/mi><annotation encoding=\"application/x-tex\">I<\/annotation><\/semantics><\/math>\nist zum Netz positiv und\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>X<\/mi><mi>s<\/mi><\/msub><annotation encoding=\"application/x-tex\">X_s<\/annotation><\/semantics><\/math>\ndie Synchronreaktanz. Mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>δ<\/mi><mo>=<\/mo><mrow><mi mathvariant=\"normal\">arg<\/mi><mo>&#8289;<\/mo><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>E<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>−<\/mo><mrow><mi mathvariant=\"normal\">arg<\/mi><mo>&#8289;<\/mo><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>V<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\delta=\\arg(E)-\\arg(V)<\/annotation><\/semantics><\/math>\nergibt sich die dreiphasige Wirkleistung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P<\/mi><mo>=<\/mo><mn>3<\/mn><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>V<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mrow><mi mathvariant=\"normal\">sin<\/mi><mo>&#8289;<\/mo><\/mrow><mi>δ<\/mi><mi>/<\/mi><msub><mi>X<\/mi><mi>s<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">P=3|E||V|\\sin\\delta/X_s<\/annotation><\/semantics><\/math>.\nEin negatives\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>δ<\/mi><annotation encoding=\"application/x-tex\">\\delta<\/annotation><\/semantics><\/math>\nbedeutet in dieser Konvention Motorbetrieb. Für eine Schenkelpolmaschine\noder gesättigte Maschine reicht das Modell im Allgemeinen nicht aus.<\/p>\n<figure>\n<img src=\"../learning-courses-university-electrical-engineering-de/media/img/U_ELG_162_DE.svg\" alt=\"Synchronmaschinen\" />\n<figcaption aria-hidden=\"true\">Synchronmaschinen<\/figcaption>\n<\/figure>\n<p><em>Abbildung: Eigenes schematisches Lehrmodell; keine Auslegungs-\noder Prüfanleitung.<\/em><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel<\/h2>\n<p>Bei 50 Hz und zwei Polpaaren beträgt die Drehzahl 1500 min⁻¹. Mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>E<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>V<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo>=<\/mo><mn>100<\/mn><\/mrow><annotation encoding=\"application/x-tex\">|E|=|V|=100<\/annotation><\/semantics><\/math>\nV pro Phase,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>X<\/mi><mi>s<\/mi><\/msub><mo>=<\/mo><mn>5<\/mn><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">Ω<\/mi><\/mrow><annotation encoding=\"application/x-tex\">X_s=5\\,\\Omega<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>δ<\/mi><mo>=<\/mo><msup><mn>30<\/mn><mo>∘<\/mo><\/msup><\/mrow><annotation encoding=\"application/x-tex\">\\delta=30^\\circ<\/annotation><\/semantics><\/math>\nerhält man\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P<\/mi><mo>=<\/mo><mn>3000<\/mn><\/mrow><annotation encoding=\"application/x-tex\">P=3000<\/annotation><\/semantics><\/math>\nW. Die mechanische Winkelgeschwindigkeit ist etwa 157,08 rad/s; ohne\nVerluste entspricht dies einem abgegebenen elektrischen Leistungsbetrag\nbei einem antreibenden Drehmoment von rund 19,1 N m. Bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>δ<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\delta=0<\/annotation><\/semantics><\/math>\nverschwindet die Wirkleistung im idealisierten Modell.<\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Stabilität und Anwendungen<\/h2>\n<p>Im einfachen Modell wächst die Wirkleistung für positive Winkel unter\n90° mit dem Winkel. Der Maximalwert allein ist keine zulässige\nBetriebsgrenze: Strom, thermische Auslegung, Erregung und dynamische\nStabilität müssen berücksichtigt werden. Synchronmaschinen finden sich\nin Generatoren und geregelten Antrieben. Das Verhalten bei Störungen\nbenötigt ein dynamisches Modell mit mechanischer Trägheit und\nelektrischen Zuständen.<\/p>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Welche Drehzahl ergibt sich bei 50 Hz und drei Polpaaren?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Wie groß ist P bei 30° und doppeltem X_s?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Warum ist der Leistungswinkel nicht der mechanische\nRotorwinkel?<\/div><\/li>\n<\/ol>\n<details class=\"lc-solutions\" data-lc-section=\"S5\"><summary>Lösungen anzeigen<\/summary>\n<div>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">1000 min⁻¹.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">1500 W bei sonst unveränderten Daten.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Der Leistungswinkel beschreibt elektrische Zeiger; die elektrische\nWinkeländerung ist p-mal die mechanische.<\/div><\/li>\n<\/ol>\n<\/div>\n<\/details>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen<\/h2>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a\nhref=\"https://ocw.mit.edu/courses/6-685-electric-machines-fall-2013/a10eb941769a0f5fa6a7460a8a7bb201_MIT6_685F13_chapter4.pdf\">J.\nL. Kirtley, MIT 6.685 – Elementary Synchronous Machine Models<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · PDF\ntext lines 299–378; balanced operation; screenshot failed · Zuletzt\nabgerufen: 2026-11-25 · Inhaltlich geprüft: 2026-11-25<\/div><\/li>\n<\/ul>\n<\/article>","university_electrical_engineering_core_de:M23-L4":"<article class=\"lesson-standard\"><h1 id=\"L4\">M23-L4 – Asynchronmaschinen<\/h1>\n<p><strong>Kursbereich:<\/strong> M23 – Bachelor: Elektrische Maschinen und Transformatoren<\/p>\n<p><strong>Niveau:<\/strong> Bachelor · Grundlagen<\/p>\n<p><strong>Vorwissen:<\/strong> <a\nhref=\"index.html?course=university_electrical-engineering-core&amp;module=M23&amp;lesson=L3&amp;syslang=de&amp;doclang=de&amp;theme=light\">M23-L3<\/a>.<\/p>\n<p><strong>Lernziel:<\/strong> Schlupf, Rotorfrequenz und Leistungsbilanz\neiner Asynchronmaschine bestimmen.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Induktion und Schlupf<\/h2>\n<p>Beim Käfigläufer entstehen Rotorströme durch die Relativbewegung\nzwischen Statorfeld und Rotor. Für die Synchrondrehzahl\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>n<\/mi><mi>s<\/mi><\/msub><annotation encoding=\"application/x-tex\">n_s<\/annotation><\/semantics><\/math>\nund die Rotordrehzahl\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>n<\/mi><annotation encoding=\"application/x-tex\">n<\/annotation><\/semantics><\/math>\ngilt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>s<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>n<\/mi><mi>s<\/mi><\/msub><mo>−<\/mo><mi>n<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><msub><mi>n<\/mi><mi>s<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">s=(n_s-n)/n_s<\/annotation><\/semantics><\/math>.\nDie Rotorstromfrequenz beträgt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>f<\/mi><mi>r<\/mi><\/msub><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>s<\/mi><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>f<\/mi><\/mrow><annotation encoding=\"application/x-tex\">f_r=|s|f<\/annotation><\/semantics><\/math>.\nBeim motorischen Betrieb in Feldrichtung liegt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>0<\/mn><mo>&lt;<\/mo><mi>s<\/mi><mo>&lt;<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">0&lt;s&lt;1<\/annotation><\/semantics><\/math>;\nbei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>s<\/mi><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">s=1<\/annotation><\/semantics><\/math>\nsteht der Rotor und bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>s<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">s=0<\/annotation><\/semantics><\/math>\nverschwindet im idealen Käfigmodell die induzierte Rotorspannung.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Ersatzschaltung und Leistung<\/h2>\n<p>Der auf die Statorseite bezogene Rotorzweig lautet im stationären\nsymmetrischen Modell\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>R<\/mi><mn>2<\/mn><\/msub><mi>′<\/mi><mi>/<\/mi><mi>s<\/mi><mo>+<\/mo><mi>j<\/mi><msub><mi>X<\/mi><mn>2<\/mn><\/msub><mi>′<\/mi><\/mrow><annotation encoding=\"application/x-tex\">R_2\\prime/s+jX_2\\prime<\/annotation><\/semantics><\/math>\nfür\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>s<\/mi><mo>≠<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">s\\ne0<\/annotation><\/semantics><\/math>.\nBei motorischem Betrieb beträgt die Luftspaltleistung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>P<\/mi><mi>δ<\/mi><\/msub><mo>=<\/mo><mn>3<\/mn><msub><mi>I<\/mi><mn>2<\/mn><\/msub><msup><mi>′<\/mi><mn>2<\/mn><\/msup><msub><mi>R<\/mi><mn>2<\/mn><\/msub><mi>′<\/mi><mi>/<\/mi><mi>s<\/mi><\/mrow><annotation encoding=\"application/x-tex\">P_\\delta=3I_2\\prime^2 R_2\\prime/s<\/annotation><\/semantics><\/math>.\nDer Rotor-Kupferverlust ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>P<\/mi><mrow><mi>C<\/mi><mi>u<\/mi><mn>2<\/mn><\/mrow><\/msub><mo>=<\/mo><mi>s<\/mi><msub><mi>P<\/mi><mi>δ<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">P_{Cu2}=sP_\\delta<\/annotation><\/semantics><\/math>,\ndie umgesetzte mechanische Leistung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>P<\/mi><mrow><mi>e<\/mi><mi>m<\/mi><\/mrow><\/msub><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>−<\/mo><mi>s<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><msub><mi>P<\/mi><mi>δ<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">P_{em}=(1-s)P_\\delta<\/annotation><\/semantics><\/math>.\nNach Abzug mechanischer Verluste bleibt die Wellenleistung. Das\nDrehmoment ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>T<\/mi><mi>e<\/mi><\/msub><mo>=<\/mo><msub><mi>P<\/mi><mi>δ<\/mi><\/msub><mi>/<\/mi><msub><mi>ω<\/mi><mi>s<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">T_e=P_\\delta/\\omega_s<\/annotation><\/semantics><\/math>.<\/p>\n<figure>\n<img src=\"../learning-courses-university-electrical-engineering-de/media/img/U_ELG_163_DE.svg\" alt=\"Asynchronmaschinen\" />\n<figcaption aria-hidden=\"true\">Asynchronmaschinen<\/figcaption>\n<\/figure>\n<p><em>Abbildung: Eigenes schematisches Lehrmodell; keine Auslegungs-\noder Prüfanleitung.<\/em><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel<\/h2>\n<p>Ein vierpoliger 50-Hz-Motor dreht mit 1440 min⁻¹. Es ergeben sich\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>n<\/mi><mi>s<\/mi><\/msub><mo>=<\/mo><mn>1500<\/mn><\/mrow><annotation encoding=\"application/x-tex\">n_s=1500<\/annotation><\/semantics><\/math>\nmin⁻¹,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>s<\/mi><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>04<\/mn><\/mrow><annotation encoding=\"application/x-tex\">s=0,04<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>f<\/mi><mi>r<\/mi><\/msub><mo>=<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">f_r=2<\/annotation><\/semantics><\/math>\nHz. Bei 5 kW Luftspaltleistung entfallen 200 W auf Rotor-Kupferverluste\nund 4,8 kW auf die umgesetzte mechanische Leistung. Das\nelektromagnetische Drehmoment beträgt rund 31,8 N m. Statorverluste sind\nvor, mechanische Verluste nach dem Luftspaltmodell zu bilanzieren.<\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Kennlinie und Regelung<\/h2>\n<p>Mit wachsendem Schlupf steigt das Drehmoment zunächst, erreicht ein\nKippmoment und sinkt im vereinfachten Modell bei weiter steigendem\nSchlupf. Frequenzumrichter können die Drehfelddrehzahl verändern; bei\nkonstantem Verhältnis Spannung zu Frequenz bleibt der Fluss im\ngeeigneten Frequenzbereich näherungsweise konstant. Bei kleinen\nFrequenzen wird der Spannungsabfall am Statorwiderstand wichtig. Anlauf,\nKühlung, Strom und Drehmoment sind getrennte Auslegungsgrenzen.<\/p>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Wie groß ist der Schlupf bei 1470 min⁻¹ und 1500 min⁻¹\nsynchron?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Wie groß sind Rotorverluste bei 5 kW Luftspaltleistung und 2 %\nSchlupf?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Was bedeutet negativer Schlupf bei positiver Drehrichtung?<\/div><\/li>\n<\/ol>\n<details class=\"lc-solutions\" data-lc-section=\"S5\"><summary>Lösungen anzeigen<\/summary>\n<div>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">0,02 bzw. 2 %.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">100 W.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Der Rotor läuft übersynchron; generatorischer Betrieb ist\nmöglich.<\/div><\/li>\n<\/ol>\n<\/div>\n<\/details>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen<\/h2>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a\nhref=\"https://www.ocw.mit.edu/courses/6-061-introduction-to-electric-power-systems-spring-2011/01f878366fe651f1b95e9ed7fc24c644_MIT6_061S11_ch10.pdf\">J.\nL. Kirtley, MIT 6.061 – Analytic Design Evaluation of Induction\nMachines<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · PDF text lines 517–539, 2357–2419; slip and air-gap\npower; screenshot failed · Zuletzt abgerufen: 2026-11-25 · Inhaltlich\ngeprüft: 2026-11-25<\/div><\/li>\n<\/ul>\n<\/article>","university_electrical_engineering_core_de:M23-L5":"<article class=\"lesson-standard\"><h1 id=\"L5\">M23-L5 – Verluste, Thermik und Antriebsauswahl<\/h1>\n<p><strong>Kursbereich:<\/strong> M23 – Bachelor: Elektrische Maschinen und Transformatoren<\/p>\n<p><strong>Niveau:<\/strong> Bachelor · Grundlagen<\/p>\n<p><strong>Vorwissen:<\/strong> <a\nhref=\"index.html?course=university_electrical-engineering-core&amp;module=M23&amp;lesson=L4&amp;syslang=de&amp;doclang=de&amp;theme=light\">M23-L4<\/a>.<\/p>\n<p><strong>Lernziel:<\/strong> Wirkungsgrad und thermische Belastung\nmodellieren und Antriebe anhand eines Lastprofils vergleichen.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Energiefluss und Verlustarten<\/h2>\n<p>Im stationären Motorbetrieb gilt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>P<\/mi><mrow><mi>i<\/mi><mi>n<\/mi><\/mrow><\/msub><mo>=<\/mo><msub><mi>P<\/mi><mrow><mi>s<\/mi><mi>h<\/mi><mi>a<\/mi><mi>f<\/mi><mi>t<\/mi><\/mrow><\/msub><mo>+<\/mo><msub><mi>P<\/mi><mi>v<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">P_{in}=P_{shaft}+P_v<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>η<\/mi><mo>=<\/mo><msub><mi>P<\/mi><mrow><mi>s<\/mi><mi>h<\/mi><mi>a<\/mi><mi>f<\/mi><mi>t<\/mi><\/mrow><\/msub><mi>/<\/mi><msub><mi>P<\/mi><mrow><mi>i<\/mi><mi>n<\/mi><\/mrow><\/msub><\/mrow><annotation encoding=\"application/x-tex\">\\eta=P_{shaft}/P_{in}<\/annotation><\/semantics><\/math>.\nZu\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>P<\/mi><mi>v<\/mi><\/msub><annotation encoding=\"application/x-tex\">P_v<\/annotation><\/semantics><\/math>\ngehören Wicklungs-, Kern-, mechanische und zusätzliche lastabhängige\nVerluste. Bei einem Drehstrommotor mit gleichen Phasenwiderständen ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>P<\/mi><mrow><mi>C<\/mi><mi>u<\/mi><\/mrow><\/msub><mo>=<\/mo><mn>3<\/mn><msup><mi>I<\/mi><mn>2<\/mn><\/msup><mi>R<\/mi><\/mrow><annotation encoding=\"application/x-tex\">P_{Cu}=3I^2R<\/annotation><\/semantics><\/math>\nfür sinusförmige Phasenströme. Die Bilanz eines Antriebssystems umfasst\nzusätzlich Umrichter und gegebenenfalls Getriebe. Wirkungsgrade werden\nbei gemeinsamem Betriebspunkt multipliziert, nicht addiert.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Thermisches Ersatzmodell<\/h2>\n<p>Für ein konzentriertes Modell mit Wärmewiderstand\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>R<\/mi><mi>θ<\/mi><\/msub><annotation encoding=\"application/x-tex\">R_\\theta<\/annotation><\/semantics><\/math>,\nWärmekapazität\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>C<\/mi><mi>θ<\/mi><\/msub><annotation encoding=\"application/x-tex\">C_\\theta<\/annotation><\/semantics><\/math>\nund Temperaturerhöhung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><mi>T<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\Delta T<\/annotation><\/semantics><\/math>\ngilt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>C<\/mi><mi>θ<\/mi><\/msub><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">d<\/mi><mi mathvariant=\"normal\">Δ<\/mi><mi>T<\/mi><mi>/<\/mi><mi mathvariant=\"normal\">d<\/mi><mi>t<\/mi><mo>=<\/mo><msub><mi>P<\/mi><mi>v<\/mi><\/msub><mo>−<\/mo><mi mathvariant=\"normal\">Δ<\/mi><mi>T<\/mi><mi>/<\/mi><msub><mi>R<\/mi><mi>θ<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">C_\\theta\\,\\mathrm d\\Delta T/\\mathrm dt=P_v-\\Delta T/R_\\theta<\/annotation><\/semantics><\/math>.\nBei konstantem Verlust und anfänglicher Umgebungstemperatur folgt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><mi>T<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><msub><mi>P<\/mi><mi>v<\/mi><\/msub><msub><mi>R<\/mi><mi>θ<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>−<\/mo><msup><mi>e<\/mi><mrow><mi>−<\/mi><mi>t<\/mi><mi>/<\/mi><mi>τ<\/mi><\/mrow><\/msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\Delta T(t)=P_vR_\\theta(1-e^{-t/\\tau})<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>τ<\/mi><mo>=<\/mo><msub><mi>R<\/mi><mi>θ<\/mi><\/msub><msub><mi>C<\/mi><mi>θ<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">\\tau=R_\\theta C_\\theta<\/annotation><\/semantics><\/math>.\nLokale Heißpunkte, veränderliche Kühlung und temperaturabhängige\nVerluste sind nicht enthalten.<\/p>\n<figure>\n<img src=\"../learning-courses-university-electrical-engineering-de/media/img/U_ELG_164_DE.svg\"\nalt=\"Verluste, Thermik und Antriebsauswahl\" />\n<figcaption aria-hidden=\"true\">Verluste, Thermik und\nAntriebsauswahl<\/figcaption>\n<\/figure>\n<p><em>Abbildung: Eigenes schematisches Lehrmodell; keine Auslegungs-\noder Prüfanleitung.<\/em><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel<\/h2>\n<p>Ein Modellmotor liefert 4,5 kW bei 5 kW Aufnahme, also\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>η<\/mi><mo>=<\/mo><mn>90<\/mn><mi>%<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\eta=90\\%<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>P<\/mi><mi>v<\/mi><\/msub><mo>=<\/mo><mn>500<\/mn><\/mrow><annotation encoding=\"application/x-tex\">P_v=500<\/annotation><\/semantics><\/math>\nW. Mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>R<\/mi><mi>θ<\/mi><\/msub><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>08<\/mn><\/mrow><annotation encoding=\"application/x-tex\">R_\\theta=0,08<\/annotation><\/semantics><\/math>\nK/W und\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>C<\/mi><mi>θ<\/mi><\/msub><mo>=<\/mo><mn>5000<\/mn><\/mrow><annotation encoding=\"application/x-tex\">C_\\theta=5000<\/annotation><\/semantics><\/math>\nJ/K ergeben sich 40 K stationäre Temperaturerhöhung und\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>τ<\/mi><mo>=<\/mo><mn>400<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\tau=400<\/annotation><\/semantics><\/math>\ns. Nach 400 s sind es rund 25,3 K. Bei 25 °C Umgebung entspricht die\nstationäre Modelltemperatur 65 °C, nicht zwingend der\nWicklungs-Hotspottemperatur.<\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lastprofil und Auswahl<\/h2>\n<p>Für eine virtuelle Auswahl werden Drehmoment, Drehzahl,\nBeschleunigung, Einschaltdauer und Kühlbedingungen als Zeitprofil\nerfasst. Über\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P<\/mi><mo>=<\/mo><mi>T<\/mi><mi>ω<\/mi><\/mrow><annotation encoding=\"application/x-tex\">P=T\\omega<\/annotation><\/semantics><\/math>\nfolgt der mechanische Leistungsbedarf. Ein Vergleich integriert die\nelektrische Aufnahme über den gesamten Zyklus und prüft Spitzenmoment,\nthermische Grenzen und mögliche Rückspeisung. Nennwirkungsgrad oder\nNennleistung allein reichen nicht. Reale Auswahl und Installation\nerfordern Herstellerdaten, Sicherheitsbewertung und geltende\nAnforderungen; der historische DOE-Leitfaden dient hier nur als\ntechnische Hintergrundquelle.<\/p>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Wie hoch ist die Verlustleistung bei 6 kW Aufnahme und 5,4 kW\nWellenleistung?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Wie groß ist die stationäre Temperaturerhöhung bei 600 W und 0,08\nK/W?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Wie groß ist der Gesamtwirkungsgrad für Motor 90 % und Umrichter 95\n%?<\/div><\/li>\n<\/ol>\n<details class=\"lc-solutions\" data-lc-section=\"S5\"><summary>Lösungen anzeigen<\/summary>\n<div>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">600 W.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">48 K.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">85,5 % am gemeinsamen Betriebspunkt.<\/div><\/li>\n<\/ol>\n<\/div>\n<\/details>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen<\/h2>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a\nhref=\"https://www.energy.gov/sites/default/files/2014/04/f15/amo_motors_handbook_web.pdf\">US\nDOE – Premium Efficiency Motor Selection and Application Guide<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · PDF\ntext lines 1145–1156; loss categories; screenshot failed; historical\nguide, not current regulation · Zuletzt abgerufen: 2026-11-25 ·\nInhaltlich geprüft: 2026-11-25<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://www.energy.gov/cmei/ito/motor-systems\">US DOE –\nMotor Systems<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · HTML lines 74–91; system efficiency resources and\ncases · Zuletzt abgerufen: 2026-11-25 · Inhaltlich geprüft:\n2026-11-25<\/div><\/li>\n<\/ul>\n<\/article>"};
